options.css:
.cart-header {
	display: flex;
	align-items: center;
	padding-left: 15px;
	padding-right: 15px;
}

.cart-icon {
	position: relative;
	flex-grow: 0;
	flex-basis: 15%;
}

.cart-badge {
	position: absolute;
	top: -2px;
	left: 15px;
	display: flex;
	justify-content: center;
	align-items: center;
	flex-direction: column; /* IE */
	padding: 4px 11px;
	width: 0px;
	background: #F12938;
	border-radius: 50%;
	font-family: 'Roboto Bold', sans-serif;
	font-size: 10px;
	color: white;
}

.cart-label {
	flex-grow: 0;
	flex-basis: 15%;
	font-family: 'Roboto Bold', sans-serif;
}

.cart-amount {
	flex-grow: 1;
    text-align: right;
}

.amount {
	position: relative;
	display: inline-block;
	font-size: 20px;
	font-family: 'Roboto Bold', sans-serif;
}

.cart-currency {
	position: relative;
	display: inline-block;
	font-size: 16px;
	font-family: 'Roboto Bold', sans-serif;
}

.splitter {
	border-width: 0;
	border-top: 1px solid rgb(166, 176, 185);
}
